<?php declare(strict_types=1); ?>
<article class="panel"><header class="panel-head"><div><span class="eyebrow">Payment instructions</span><h2>Verified external references</h2></div></header><div class="table-wrap"><table class="data-table"><thead><tr><th>Instruction</th><th>Supplier</th><th>Method</th><th>Status</th><th>Cooling until</th><th>Vault reference</th></tr></thead><tbody><?php foreach($instructions as$i): ?><tr><td><?= h($i['instruction_number']) ?></td><td><?= h(data_supplier_name($i['supplier_id'])) ?></td><td><?= h(status_label($i['payment_method'])) ?></td><td><?= badge($i['status']) ?></td><td><?= h(date_us($i['cooling_until'])) ?></td><td><?= h($i['vault_reference']) ?></td></tr><?php endforeach; ?></tbody></table></div></article></section>
<aside class="ap-stack"><article class="panel"><header class="panel-head"><div><span class="eyebrow">New credit</span><h2>Record supplier credit</h2></div></header><form class="ap-form" method="post" action="<?= h(app_url('accounts-payable-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="save_credit"><label><span>Company</span><select name="company_id"><?= company_options($company) ?></select></label><label><span>Supplier</span><select name="supplier_id"><?php foreach(data_visible_collection('suppliers')as$s): ?><option value="<?= (int)$s['id'] ?>"><?= h($s['name']) ?></option><?php endforeach; ?></select></label><label><span>Credit type</span><select name="credit_type"><?php foreach(['credit_memo','rebate','overpayment_recovery','return_credit','quality_recovery','freight_claim','pricing_adjustment','tax_adjustment']as$t): ?><option value="<?= h($t) ?>"><?= h(status_label($t)) ?></option><?php endforeach; ?></select></label><label><span>Credit memo</span><input name="credit_memo_number" required></label><label><span>Credit date</span><input type="date" name="credit_date" value="<?= date('Y-m-d') ?>"></label><label><span>Expiration date</span><input type="date" name="expiration_date" value="<?= date('Y-m-d',strtotime('+1 year')) ?>"></label><label><span>Amount</span><input type="number" min="0.01" step="0.01" name="original_amount" required></label><label><span>Reviewer</span><select name="reviewer_id"><?= user_options($reviewer) ?></select></label><label class="span-2"><span>Evidence</span><textarea name="evidence_note" required>Supplier credit recorded from invoice, return, quality, freight, pricing, or recovery evidence for independent finance validation.</textarea></label><?php if(can('accounts_payable.create')): ?><button class="button primary span-2">Record credit for review</button><?php endif; ?></form></article>
<article class="panel"><header class="panel-head"><div><span class="eyebrow">Fraud-resistant change control</span><h2>Verify payment instruction</h2></div></header><form class="ap-form" method="post" action="<?= h(app_url('accounts-payable-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="save_instruction"><label><span>Company</span><select name="company_id"><?= company_options($company) ?></select></label><label><span>Supplier</span><select name="supplier_id"><?php foreach(data_visible_collection('suppliers')as$s): ?><option value="<?= (int)$s['id'] ?>"><?= h($s['name']) ?></option><?php endforeach; ?></select></label><label><span>Method</span><select name="payment_method"><?php foreach(accounts_payable_payment_methods()as$m): ?><option value="<?= h($m) ?>"><?= h(status_label($m)) ?></option><?php endforeach; ?></select></label><label><span>External vault reference</span><input name="vault_reference" required></label><label><span>Requester</span><select name="requested_by"><?= user_options($owner) ?></select></label><label><span>Verifier</span><input value="<?= h(data_user_name($owner)) ?>" disabled><input type="hidden" name="verified_by" value="<?= $owner ?>"></label><label><span>Effective date</span><input type="date" name="effective_date" value="<?= date('Y-m-d',strtotime('+2 days')) ?>"></label><label><span>Cooling until</span><input type="date" name="cooling_until" value="<?= date('Y-m-d',strtotime('+5 days')) ?>"></label><label class="span-2"><span>Callback evidence</span><textarea name="callback_evidence" required>Independent callback completed using a trusted supplier-master contact; no banking credentials stored in the application.</textarea></label><label class="span-2"><span>Change reason</span><textarea name="change_reason" required>Verified payment-instruction reference created or changed under dual control.</textarea></label><?php if(can('accounts_payable.approve')): ?><button class="button primary span-2">Verify instruction reference</button><?php endif; ?></form></article></aside></div>
